import { useState, useEffect } from 'react';
import API from '../../api/axios';
import toast from 'react-hot-toast';
import { useNavigate } from 'react-router-dom';

export default function AdminCheckout() {
  const [customers, setCustomers] = useState([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [fiatAmount, setFiatAmount] = useState('');
  const [loading, setLoading] = useState(false);
  const [activeSession, setActiveSession] = useState(null);
  
  const adminInfo = JSON.parse(localStorage.getItem('userInfo')) || {};
  const navigate = useNavigate();

  // Fetch customers belonging specifically to this admin's company
  useEffect(() => {
    const fetchCustomers = async () => {
      if (!adminInfo.companyId?._id && !adminInfo.companyId) return;
      const compId = adminInfo.companyId._id || adminInfo.companyId;

      try {
        const { data } = await API.get(`/users/company/${compId}`);
        setCustomers(data);
      } catch (error) {
        toast.error('Failed to load customers');
      }
    };
    fetchCustomers();
  }, []);

  const handleInitiateCheckout = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const { data } = await API.post('/transactions/initiate', {
        customerId: selectedCustomerId,
        fiatAmount: Number(fiatAmount)
      });

      setActiveSession({
        transactionId: data.transactionId,
        pointsRequired: data.pointsRequired,
        fiatAmount
      });
      toast.success(data.message);
    } catch (error) {
      toast.error(error.response?.data?.message || 'Checkout initiation failed');
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = async () => {
    await API.post('/auth/logout');
    localStorage.removeItem('userInfo');
    navigate('/');
  };

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-2xl mx-auto space-y-6">
        
        {/* Header */}
        <div className="flex justify-between items-center bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
          <div>
            <h1 className="text-xl font-bold text-gray-900">POS Checkout Terminal</h1>
            <p className="text-sm text-gray-500">Logged in as Admin • {adminInfo.fullName}</p>
          </div>
          <button 
            onClick={handleLogout}
            className="px-4 py-2 bg-red-50 hover:bg-red-100 text-red-600 font-medium rounded-lg text-sm transition"
          >
            Sign Out
          </button>
        </div>

        {/* Checkout Form */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
          {!activeSession ? (
            <form onSubmit={handleInitiateCheckout} className="space-y-4">
              <div>
                <label className="block text-xs font-semibold uppercase tracking-wider text-gray-600 mb-1">Select Customer</label>
                <select
                  value={selectedCustomerId}
                  onChange={(e) => setSelectedCustomerId(e.target.value)}
                  required
                  className="w-full px-4 py-2.5 bg-gray-50 border border-gray-300 rounded-lg text-gray-800 focus:outline-none focus:ring-2 focus:ring-gray-900 text-sm"
                >
                  <option value="" disabled>-- Choose a Customer --</option>
                  {customers.map((c) => (
                    <option key={c._id} value={c._id}>
                      {c.fullName} ({c.email}) - Balance: {c.pointBalance} pts
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-xs font-semibold uppercase tracking-wider text-gray-600 mb-1">Purchase Amount (₦)</label>
                <input
                  type="number"
                  value={fiatAmount}
                  onChange={(e) => setFiatAmount(e.target.value)}
                  placeholder="e.g. 1500"
                  required
                  className="w-full px-4 py-2.5 bg-gray-50 border border-gray-300 rounded-lg text-gray-800 focus:outline-none focus:ring-2 focus:ring-gray-900 text-sm"
                />
              </div>

              <button
                type="submit"
                disabled={loading}
                className="w-full py-3 bg-gray-900 hover:bg-gray-800 text-white font-medium rounded-lg text-sm transition shadow-sm disabled:opacity-50"
              >
                {loading ? 'Locking Terminal...' : 'Initiate Checkout & Request Tap'}
              </button>
            </form>
          ) : (
            <div className="text-center space-y-4 py-8">
              <div className="w-16 h-16 bg-yellow-50 text-yellow-600 rounded-full flex items-center justify-center mx-auto animate-pulse text-2xl font-bold">
                💳
              </div>
              <h3 className="text-xl font-bold text-gray-900">Waiting for Card Tap...</h3>
              <p className="text-sm text-gray-500 max-w-sm mx-auto">
                Terminal locked for bill of <span className="font-semibold text-gray-900">₦{activeSession.fiatAmount}</span> ({activeSession.pointsRequired} points). Ask the customer to tap their RFID card on the reader.
              </p>
              <button
                onClick={() => setActiveSession(null)}
                className="px-6 py-2.5 bg-gray-100 hover:bg-gray-200 text-gray-700 font-medium rounded-lg text-sm transition"
              >
                Cancel / New Transaction
              </button>
            </div>
          )}
        </div>

      </div>
    </div>
  );
}
